from bisect import bisect_right
from functools import lru_cache
from math import isqrt


def _integer_nth_root(value, exponent):
    low, high = 1, value
    while low < high:
        mid = (low + high + 1) // 2
        if mid ** exponent <= value:
            low = mid
        else:
            high = mid - 1
    return low


@lru_cache(maxsize=1)
def _nonsquare_higher_powers():
    """Return non-square powers a**b for b >= 3 up to 10**18."""
    limit = 10**18
    values = set()
    for exponent in range(3, 60):
        root = _integer_nth_root(limit, exponent)
        for base in range(2, root + 1):
            value = base ** exponent
            if isqrt(value) ** 2 != value:
                values.add(value)
    return tuple(sorted(values))


def count_power_representations(n: int) -> int:
    """ Count how many integers x between 1 and n (inclusive) can be expressed as x = a^b
    where a is a positive integer and b is an integer greater than or equal to 2.

    Args:
        n: The upper bound (1 <= n <= 10^18)

    Returns:
        The count of integers that can be expressed as x = a^b where b >= 2

    >>> count_power_representations(99)
    12
    >>> count_power_representations(1000000000000000000)
    1001003332
    """
    return isqrt(n) + bisect_right(_nonsquare_higher_powers(), n)

