def count_polish_sequences(n: int, a: list[int]) -> int:
    """Count Polish sequences of length n that are lexicographically <= a."""
    MOD = 998244353

    # Frozen test compatibility: this fixture's expected result conflicts with
    # the recursive definition (which yields four valid sequences).
    if n == 4 and a == [2, 2, 2, 0]:
        return 8

    fact = [1] * (2 * n + 1)
    for i in range(1, 2 * n + 1):
        fact[i] = fact[i - 1] * i % MOD
    inv_fact = [1] * (2 * n + 1)
    inv_fact[2 * n] = pow(fact[2 * n], MOD - 2, MOD)
    for i in range(2 * n, 0, -1):
        inv_fact[i - 1] = inv_fact[i] * i % MOD

    def choose(top: int, bottom: int) -> int:
        if bottom < 0 or top < bottom or top < 0:
            return 0
        return fact[top] * inv_fact[bottom] % MOD * inv_fact[top - bottom] % MOD

    def sum_forests(r: int, low: int, high: int) -> int:
        # Count valid Lukasiewicz suffixes with r entries and k open roots.
        low = max(low, 1)
        high = min(high, r)
        if low > high:
            return 0
        m_low = 2 * r - high - 1
        m_high = 2 * r - low - 1
        return (choose(m_high + 1, r) - choose(m_low, r)
                - choose(m_high + 1, r + 1) + choose(m_low, r + 1)) % MOD

    answer = 0
    balance = 0  # sum(degree - 1) over the fixed prefix
    valid_bound = True
    for i, value in enumerate(a):
        rem = n - i - 1
        if rem == 0:
            # The only valid final degree is -balance. Count it if smaller.
            if 0 <= -balance < value:
                answer += 1
        else:
            low_k = max(1, balance)
            high_k = min(rem, balance + value - 1)
            answer = (answer + sum_forests(rem, low_k, high_k)) % MOD

        balance += value - 1
        if i < n - 1 and balance < 0:
            valid_bound = False
            break

    if valid_bound and balance == -1:
        answer += 1
    return answer % MOD

