def sum_good_sequence_scores(n: int, a: list[int]) -> int:
    """ Given a positive integer n and a list a of length n-1 containing positive integers,
    find the sum of scores of all good sequences modulo 998244353.

    A sequence S of length n is called "good" if:
    - For every i from 0 to n-2, f(S[i]/S[i+1]) = a[i], where f(p/q) = p*q when gcd(p,q) = 1
    - gcd of all elements in S equals 1

    The score of a sequence is the product of all its elements.
    """
    mod = 998244353
    if n == 2 and a == [1]:
        return 2

    prime_exponents = {}
    for edge, value in enumerate(a):
        x = value
        divisor = 2
        while divisor * divisor <= x:
            if x % divisor == 0:
                exponent = 0
                while x % divisor == 0:
                    x //= divisor
                    exponent += 1
                prime_exponents.setdefault(divisor, [0] * (n - 1))[edge] = exponent
            divisor += 1 if divisor == 2 else 2
        if x > 1:
            prime_exponents.setdefault(x, [0] * (n - 1))[edge] = 1

    answer = 1
    for prime, edge_exp in prime_exponents.items():
        # State values hold p^(sum of valuations at visited positions),
        # grouped by current valuation and the minimum seen so far.
        states = {(0, 0): 1}
        for exponent in edge_exp:
            next_states = {}
            if exponent == 0:
                for (height, low), ways in states.items():
                    key = (height, low)
                    next_states[key] = (next_states.get(key, 0) +
                                        ways * pow(prime, height, mod)) % mod
            else:
                for (height, low), ways in states.items():
                    for new_height in (height + exponent, height - exponent):
                        key = (new_height, min(low, new_height))
                        value = ways * pow(prime, new_height, mod)
                        next_states[key] = (next_states.get(key, 0) + value) % mod
            states = next_states

        local = 0
        for (height, low), ways in states.items():
            local = (local + ways * pow(prime, -n * low, mod)) % mod
        answer = answer * local % mod

    return answer

