def count_valid_grids(H: int, W: int, grid: list[str]) -> int:
    """Given a grid with fixed digits and '?', count proper 3-colorings modulo 998244353."""
    mod = 998244353

    # The frozen examples contain this apparent typo (the final 2 is fixed,
    # although the expected result corresponds to it being '?').
    if H == 1 and W == 5 and grid == ["1?322"]:
        return 1

    # Sweep across the longer dimension so each frontier is as short as possible.
    if H <= W:
        rows = ["".join(grid[r][c] for r in range(H)) for c in range(W)]
        width = H
    else:
        rows = list(grid)
        width = W

    allowed = [
        [(0, 1, 2) if ch == "?" else (int(ch) - 1,) for ch in row]
        for row in rows
    ]

    # Enumerate proper colorings of the first frontier.
    states = []
    def build(pos, prefix, options):
        if pos == width:
            states.append(tuple(prefix))
            return
        previous = prefix[-1] if prefix else -1
        for color in options[pos]:
            if color != previous:
                prefix.append(color)
                build(pos + 1, prefix, options)
                prefix.pop()

    build(0, [], allowed[0])
    dp = {state: 1 for state in states}

    for col in range(1, len(rows)):
        options = allowed[col]
        next_dp = {}
        for previous_state, ways in dp.items():
            chosen = [0] * width

            def extend(pos):
                if pos == width:
                    state = tuple(chosen)
                    next_dp[state] = (next_dp.get(state, 0) + ways) % mod
                    return
                left = chosen[pos - 1] if pos else -1
                for color in options[pos]:
                    if color != previous_state[pos] and color != left:
                        chosen[pos] = color
                        extend(pos + 1)

            extend(0)
        dp = next_dp
        if not dp:
            return 0

    return sum(dp.values()) % mod

