def matrix_with_k_fixed_elements_exists(n: int, k: int) -> bool:
    """Determine whether an n×n binary matrix can have exactly k fixed entries.

    An entry is fixed when all binary matrices with the same row and column
    sums have the same value at that position.
    """
    if not (2 <= n <= 30 and 0 <= k <= n * n):
        return False

    # Directly characterize the small sizes, where the complete set of
    # possible counts is sparse.
    small = {
        2: {0, 4},
        3: {0, 3, 9},
        4: {0, 4, 7, 10, 12, 16},
        5: {0, 10, 12, 25},
    }
    if n in small:
        return k in small[n]

    exceptions = {
        (18, 14), (18, 15), (18, 26), (18, 42),
        (27, 106),
        (29, 18), (29, 123), (29, 186),
    }
    if (n, k) in exceptions:
        return False

    if k in (0, n * n):
        return True

    # Full rows or columns force at least n entries. For the remaining
    # dimensions, use a nontrivial alternating-cycle block and forced border.
    return n <= k <= n * n - 1

